"use client"

import * as React from "react"
import { Command as CommandPrimitive } from "cmdk"

import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import { useInk, useInkSeed, useMergedRef } from "@/lib/ink/react"
import {
  commandInputRecipe,
  commandItemRecipe,
  commandPanelRecipe,
} from "@/lib/ink/recipes/command-ink"
import { cn } from "@/lib/utils"

function Command({
  className,
  seed,
  children,
  ref,
  ...props
}: React.ComponentProps<typeof CommandPrimitive> & { seed?: string | number }) {
  const { hostRef, hostProps, node } = useInk({
    recipe: commandPanelRecipe,
    params: {},
    kind: "command",
    seed,
    still: true,
  })

  return (
    <CommandPrimitive
      ref={ref}
      data-slot="command"
      className={cn("relative flex h-full w-full flex-col overflow-hidden rounded-[var(--radius-md)]", className)}
      {...props}
    >
      <div
        ref={hostRef}
        {...hostProps}
        className="pointer-events-none absolute inset-0 overflow-hidden rounded-[inherit]"
        aria-hidden
      >
        {node}
      </div>
      <div className="relative z-[1] flex h-full flex-col overflow-hidden">{children}</div>
    </CommandPrimitive>
  )
}

function CommandDialog({
  title = "Command palette",
  description = "Search for a command to run…",
  children,
  className,
  ...props
}: React.ComponentProps<typeof Dialog> & {
  title?: string
  description?: string
  className?: string
}) {
  return (
    <Dialog {...props}>
      <DialogContent bare className={cn("max-w-lg overflow-hidden p-0", className)}>
        <DialogHeader className="sr-only">
          <DialogTitle>{title}</DialogTitle>
          <DialogDescription>{description}</DialogDescription>
        </DialogHeader>
        <Command className="shadow-[0_16px_48px_-12px_rgb(var(--sd-shade)/0.22)]">{children}</Command>
      </DialogContent>
    </Dialog>
  )
}

function CommandInput({
  className,
  seed,
  ref,
  ...props
}: React.ComponentProps<typeof CommandPrimitive.Input> & { seed?: string | number }) {
  const disabled = !!props.disabled
  const { hostRef, hostProps, node } = useInk({
    recipe: commandInputRecipe,
    params: { disabled },
    kind: "command-input",
    seed,
    still: true,
  })

  return (
    <div
      data-slot="command-input-wrapper"
      data-ink-focus="within"
      className="flex items-center border-b border-[color-mix(in_srgb,var(--sd-ink)_8%,transparent)] px-3"
      cmdk-input-wrapper=""
    >
      <span className="relative z-[1] me-2 text-muted-foreground" aria-hidden>
        ⌕
      </span>
      <span
        ref={hostRef}
        {...hostProps}
        className="relative isolate my-2 flex h-8 min-w-0 flex-1 items-center rounded-[var(--radius-sm)]"
      >
        {node}
        <CommandPrimitive.Input
          ref={ref}
          data-slot="command-input"
          className={cn(
            "relative z-[1] h-full w-full bg-transparent px-2 text-sm outline-none",
            "placeholder:text-muted-foreground disabled:cursor-not-allowed disabled:opacity-60",
            className,
          )}
          {...props}
        />
      </span>
    </div>
  )
}

function CommandList({ className, ...props }: React.ComponentProps<typeof CommandPrimitive.List>) {
  return (
    <CommandPrimitive.List
      data-slot="command-list"
      className={cn("max-h-72 overflow-x-hidden overflow-y-auto p-1", className)}
      {...props}
    />
  )
}

function CommandEmpty(props: React.ComponentProps<typeof CommandPrimitive.Empty>) {
  return (
    <CommandPrimitive.Empty
      data-slot="command-empty"
      className="py-6 text-center text-sm text-muted-foreground"
      {...props}
    />
  )
}

function CommandGroup({ className, ...props }: React.ComponentProps<typeof CommandPrimitive.Group>) {
  return (
    <CommandPrimitive.Group
      data-slot="command-group"
      className={cn(
        "overflow-hidden p-1 text-foreground [&_[cmdk-group-heading]]:px-2 [&_[cmdk-group-heading]]:py-1.5 [&_[cmdk-group-heading]]:text-xs [&_[cmdk-group-heading]]:font-medium [&_[cmdk-group-heading]]:text-muted-foreground",
        className,
      )}
      {...props}
    />
  )
}

function CommandSeparator({ className, ...props }: React.ComponentProps<typeof CommandPrimitive.Separator>) {
  return (
    <CommandPrimitive.Separator
      data-slot="command-separator"
      className={cn("-mx-1 my-1 h-px bg-[color-mix(in_srgb,var(--sd-line-soft)_80%,transparent)]", className)}
      {...props}
    />
  )
}

function CommandItem({
  className,
  disabled,
  seed,
  children,
  ref,
  ...props
}: React.ComponentProps<typeof CommandPrimitive.Item> & { seed?: string | number }) {
  const itemSeed = useInkSeed(seed)
  const { hostRef, hostProps, node } = useInk({
    recipe: commandItemRecipe,
    params: { disabled: !!disabled },
    kind: "menu-item",
    seed: itemSeed,
    still: true,
  })

  return (
    <CommandPrimitive.Item
      ref={useMergedRef<HTMLDivElement>(hostRef, ref)}
      {...hostProps}
      data-slot="command-item"
      disabled={disabled}
      className={cn(
        "relative isolate flex cursor-default select-none items-center gap-2 rounded-sm px-2 py-1.5 text-sm outline-none",
        "text-foreground data-[disabled=true]:pointer-events-none data-[disabled=true]:opacity-50",
        className,
      )}
      {...props}
    >
      {node}
      <span className="relative z-[1]">{children}</span>
    </CommandPrimitive.Item>
  )
}

function CommandShortcut({ className, ...props }: React.ComponentProps<"span">) {
  return (
    <span
      data-slot="command-shortcut"
      className={cn("ms-auto text-xs tracking-widest text-muted-foreground", className)}
      {...props}
    />
  )
}

export {
  Command,
  CommandDialog,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
  CommandSeparator,
  CommandShortcut,
}

import { defineRecipe } from '@/lib/ink/recipes'
import { drawFieldWashFrame, type FieldFrameParams } from '@/lib/ink/recipes/field-wash-frame'
import { drawCompactSandSlipPanel } from '@/lib/ink/recipes/panel-wash'

export const commandPanelRecipe = defineRecipe<Record<string, never>>({
  id: 'command-panel',
  kind: 'command',
  layers: ['rest'],
  pad: 10,
  draw(ink, { w, h }) {
    ink.layer('rest', () => drawCompactSandSlipPanel(ink, w, h))
  },
})

export type CommandInputParams = FieldFrameParams

export const commandInputRecipe = defineRecipe<CommandInputParams>({
  id: 'command-input',
  kind: 'command-input',
  layers: ['rest', 'hover', 'focus', 'disabled'],
  lazy: ['focus'],
  pad: 6,
  draw(ink, { w, h }, params, ctx) {
    drawFieldWashFrame(ink, w, h, params, ctx, { radiusFactor: 0.1 })
  },
})

export { dropdownMenuItemRecipe as commandItemRecipe } from '@/lib/ink/recipes/dropdown-menu-ink'

import { wash } from '@/lib/ink/fills'
import { roundRectPoly } from '@/lib/ink/geom'
import { focusRing } from '@/lib/ink/shapes'
import { clamp } from '@/lib/ink/rng'
import { defineRecipe } from '@/lib/ink/recipes'
import { drawCompactSandSlipPanel } from '@/lib/ink/recipes/panel-wash'

export const dropdownMenuContentRecipe = defineRecipe<Record<string, never>>({
  id: 'dropdown-menu-content',
  kind: 'dropdown-menu',
  layers: ['rest'],
  pad: 8,
  draw(ink, { w, h }) {
    ink.layer('rest', () => drawCompactSandSlipPanel(ink, w, h))
  },
})

export interface DropdownMenuItemParams {
  disabled?: boolean
}

export const dropdownMenuItemRecipe = defineRecipe<DropdownMenuItemParams>({
  id: 'dropdown-menu-item',
  kind: 'menu-item',
  layers: ['rest', 'hover', 'focus', 'disabled'],
  lazy: ['focus'],
  pad: 4,
  draw(ink, { w, h }, { disabled }, ctx) {
    const r = clamp(Math.min(w, h) * 0.2, 2, 4)
    const body = roundRectPoly(0.5, 0.5, w - 1, h - 1, r)

    if (disabled) {
      if (ctx.lazyOnly) return
      ink.layer('disabled', () => {
        wash(ink, body, 'sand-shade', { alpha: 0.2, material: 'wash', wobble: 0.35 })
      })
      return
    }

    ctx.lazy('focus', (fink) => {
      wash(fink, body, 'rose-wash', { alpha: 0.38, material: 'wash', wobble: 0.65 })
      focusRing(fink, 0, 0, w, h, { r, pen: 'horizonPencil.fine', opts: { alpha: 0.7, simple: true } })
    })
    if (ctx.lazyOnly) return

    ink.layer('hover', () => {
      wash(ink, body, 'rose-wash', { alpha: 0.42, material: 'wash', wobble: 0.72 })
    })
  },
})

import { wash } from '@/lib/ink/fills'
import { roundRectPoly } from '@/lib/ink/geom'
import { box, focusRing } from '@/lib/ink/shapes'
import { clamp } from '@/lib/ink/rng'
import type { Ink } from '@/lib/ink/builder'
import type { RecipeContext } from '@/lib/ink/recipes'
import { softFill } from '@/lib/ink/recipes/wash-utils'

export interface FieldFrameParams {
  disabled?: boolean
  invalid?: boolean
  readOnly?: boolean
}

export interface FieldFrameOptions {
  /** Smaller = rounder corners on tall boxes (textarea). Default 0.14 */
  radiusFactor?: number
}

export function drawFieldWashFrame(
  ink: Ink,
  w: number,
  h: number,
  { disabled, invalid, readOnly }: FieldFrameParams,
  ctx: RecipeContext,
  opt: FieldFrameOptions = {},
) {
  const rf = opt.radiusFactor ?? 0.14
  const r = clamp(Math.min(w, h) * rf, 3.5, 10)
  const inset = 0.55
  const body = roundRectPoly(inset, inset, w - 2 * inset, h - 2 * inset, r)

  if (disabled) {
    if (ctx.lazyOnly) return
    ink.layer('disabled', () => {
      wash(ink, body, 'sand-shade', { alpha: 0.48, wobble: 0.45, material: 'wash' })
      box(ink, 0.5, 0.5, w - 1, h - 1, {
        pen: 'pencil.fine',
        corner: r,
        loose: 0.35,
        opts: { alpha: 0.35, simple: true },
      })
    })
    return
  }

  if (invalid) {
    ink.layer('invalid', () => {
      softFill(ink, body, [
        { color: 'wash-rose', alpha: 0.35, wobble: 0.8 },
        { color: 'ember', alpha: 0.18, inset: 0.6 },
      ])
      box(ink, 0.55, 0.55, w - 1.1, h - 1.1, {
        pen: 'rose.fine',
        corner: r,
        loose: 1,
        opts: { alpha: 0.75, wobble: 0.4, simple: true, color: 'danger' },
      })
    })
  }

  ctx.lazy('focus', (fink) => {
    wash(fink, body, 'star', { alpha: 0.22, wobble: 0.6, material: 'wash', inset: 0.15 })
    wash(fink, body, 'horizon', { alpha: 0.12, wobble: 0.75, material: 'wash', inset: 1.2 })
    focusRing(fink, 0, 0, w, h, {
      r,
      pen: 'horizonPencil.fine',
      opts: { alpha: 0.9, wobble: 0.32, simple: w < 120 },
    })
  })
  if (ctx.lazyOnly) return

  ink.layer('rest', () => {
    softFill(ink, body, [
      { color: 'sand-slip', alpha: 0.72, wobble: 0.55 },
      { color: 'sand', alpha: 0.28, inset: 0.8 },
    ])
    box(ink, 0.55, 0.55, w - 1.1, h - 1.1, {
      pen: readOnly ? 'pencil.fine' : 'rose.fine',
      corner: r,
      loose: readOnly ? 0.5 : 0.95,
      opts: {
        alpha: readOnly ? 0.42 : 0.58,
        wobble: 0.36,
        simple: w < 120,
        color: readOnly ? 'pencil' : 'ink-soft',
      },
    })
  })

  ink.layer('hover', () => {
    if (readOnly) return
    wash(ink, body, 'rose-wash', { alpha: 0.28, wobble: 0.85, material: 'wash' })
    box(ink, 0.8, 0.8, w - 1.6, h - 1.6, {
      pen: 'ink.fine',
      corner: r,
      loose: 0.85,
      opts: { alpha: 0.4, simple: true, color: 'horizon' },
    })
  })
}

import { roundRectPoly } from '@/lib/ink/geom'
import { box } from '@/lib/ink/shapes'
import { clamp } from '@/lib/ink/rng'
import type { Ink } from '@/lib/ink/builder'
import { softFill } from '@/lib/ink/recipes/wash-utils'

export type PanelTone = 'default' | 'lifted'

/** Compact sand-slip panel (Tooltip / Toast). */
export function drawCompactSandSlipPanel(ink: Ink, w: number, h: number) {
  const r = clamp(Math.min(w, h) * 0.1, 4, 7)
  const inset = 0.55
  const body = roundRectPoly(inset, inset, w - 2 * inset, h - 2 * inset, r)

  ink.part('fill', () => {
    softFill(ink, body, [
      { color: 'sand-slip', alpha: 0.82, wobble: 0.48 },
      { color: 'sand', alpha: 0.28, inset: 0.9, wobble: 0.55 },
      { color: 'wash-gold', alpha: 0.06, inset: 1.6, wobble: 0.9 },
    ])
  })
  box(ink, 0.55, 0.55, w - 1.1, h - 1.1, {
    pen: 'pencil.fine',
    corner: r,
    loose: 0.95,
    opts: { alpha: 0.48, wobble: 0.38, simple: w > 280 },
  })
  box(ink, 1.1, 1.1, w - 2.2, h - 2.2, {
    pen: 'ink.fine',
    corner: Math.max(2, r - 1),
    loose: 1,
    opts: { alpha: 0.18, wobble: 0.42, simple: true, color: 'line-soft' },
  })
}

/** Sand-slip panel fill + double loose border (Card / Dialog / Popover). */
export function drawSandSlipPanel(ink: Ink, w: number, h: number, tone: PanelTone = 'default') {
  const r = clamp(Math.min(w, h) * 0.04, 5, 12)
  const inset = 0.7
  const body = roundRectPoly(inset, inset, w - 2 * inset, h - 2 * inset, r)

  ink.part('fill', () => {
    softFill(ink, body, [
      { color: 'sand-slip', alpha: tone === 'lifted' ? 0.9 : 0.78, wobble: 0.5 },
      { color: 'sand', alpha: 0.32, inset: 1.2, wobble: 0.65 },
      { color: 'wash-gold', alpha: 0.08, inset: 2.4, wobble: 1.1 },
    ])
  })
  box(ink, 0.65, 0.65, w - 1.3, h - 1.3, {
    pen: 'pencil.fine',
    corner: r,
    loose: 1.15,
    opts: { alpha: 0.52, wobble: 0.42, simple: w > 420 },
  })
  box(ink, 1.4, 1.4, w - 2.8, h - 2.8, {
    pen: 'ink.fine',
    corner: Math.max(2, r - 1),
    loose: 1.25,
    opts: { alpha: 0.22, wobble: 0.5, simple: true, color: 'line-soft' },
  })
}

import type { Ink } from '@/lib/ink/builder'
import type { Pt } from '@/lib/ink/types'
import type { PaintKey } from '@/lib/ink/paint'
import { wash } from '@/lib/ink/fills'

export function softFill(
  ink: Ink,
  body: Pt[],
  layers: Array<{ color: PaintKey; alpha: number; inset?: number; wobble?: number }>,
) {
  for (const layer of layers) {
    wash(ink, body, layer.color, {
      alpha: layer.alpha,
      inset: layer.inset ?? 0.4,
      wobble: layer.wobble ?? 0.95,
      material: 'wash',
    })
  }
}
